package com.gymflow.app;
import android.content.Intent; import android.os.Bundle; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import org.json.*;
public class SetupGymActivity extends AppCompatActivity{
 @Override protected void onCreate(Bundle b){super.onCreate(b);LinearLayout r=Ui.page(this);r.addView(Ui.title(this,"Configurar gimnasio"));EditText gym=Ui.input(this,"Nombre del gimnasio");gym.setText(getSharedPreferences("gymflow",0).getString("pending_gym_name",""));r.addView(gym);TextView state=Ui.subtitle(this,"Este nombre se puede cambiar después.");r.addView(state);Button save=Ui.button(this,"Guardar y entrar");r.addView(save);save.setOnClickListener(v->{String n=gym.getText().toString().trim();if(n.isEmpty())return;try{JSONObject o=new JSONObject();o.put("owner_id",Session.uid(this));o.put("name",n);Cloud.post(this,"gf_gyms",o,(code,body)->{if(code>=200&&code<300){getSharedPreferences("gymflow",0).edit().putString("gym_name",n).remove("pending_gym_name").apply();startActivity(new Intent(this,MainActivity.class));finish();}else state.setText("Error: "+Cloud.err(body));});}catch(Exception e){state.setText(e.toString());}});setContentView(r);}
}
